function Footer({ onNavigate }) {
  return <footer className="footer"><div className="footer-inner"><div><span className="footer-brand">Gokulnaath K R</span><span className="footer-copy">Aspiring Software Engineer</span></div><div className="footer-links"><button onClick={() => onNavigate("home")}>Back to top</button><a href="/resume.pdf" target="_blank" rel="noopener noreferrer">Resume</a></div><span className="footer-copy">Built with React</span></div></footer>;
}

function ScrollToTop() {
  const [show, setShow] = useState(false);
  const [progress, setProgress] = useState(0);
  useEffect(() => {
    const onScroll = () => { setShow(window.scrollY > 560); const doc = document.documentElement; const max = doc.scrollHeight - doc.clientHeight; setProgress(max > 0 ? Math.round((window.scrollY / max) * 100) : 0); };
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return <button className={`to-top ${show ? "to-top-show" : ""}`} onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })} aria-label="Scroll to top" title={`${progress}% scrolled`}><span className="to-top-progress">{progress}</span><ArrowUp size={15} /></button>;
}

const SECTION_IDS = NAV_LINKS.map((l) => l.id);

export default function Portfolio() {
  const active = useActiveSection(SECTION_IDS);
  const [theme, setTheme] = useState(() => {
    const saved = localStorage.getItem(THEME_KEY);
    if (saved === "dark" || saved === "light") return saved;
    return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  });
  const [toast, setToast] = useState(null);
  const [modalProject, setModalProject] = useState(null);

  useEffect(() => { localStorage.setItem(THEME_KEY, theme); }, [theme]);
  useEffect(() => {
    if (!toast) return undefined;
    const t = setTimeout(() => setToast(null), 2600);
    return () => clearTimeout(t);
  }, [toast]);
  const navigate = (id) => { const el = document.getElementById(id); if (el) { el.scrollIntoView({ behavior: "smooth", block: "start" }); } };

  useEffect(() => {
    const onKey = (e) => {
      if (e.target.matches("input,textarea")) return;
      const key = e.key.toLowerCase();
      const map = { h: "home", a: "about", s: "skills", p: "projects", c: "contact" };
      if (map[key]) navigate(map[key]);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, []);
  const onToast = (message) => setToast({ message, type: "success" });

  return <div className={`portfolio-root ${theme === "dark" ? "dark-theme" : ""}`}>
    <style>{CSS}</style>
    <ScrollProgress />
    <CustomCursor />
    <Navbar active={active} onNavigate={navigate} theme={theme} setTheme={setTheme} />
    <main>
      <Hero onNavigate={navigate} onToast={onToast} />
      <About />
      <Skills />
      <Experience />
      <Projects onOpen={setModalProject} />
      <Education />
      <Certifications />
      <Contact onToast={onToast} />
    </main>
    <Footer onNavigate={navigate} />
    <ScrollToTop />
    <Toast toast={toast} />
    <ProjectModal project={modalProject} onClose={() => setModalProject(null)} />
  </div>;
}

